/**
 * Core contracts for the state-machine multi-agent workflow framework.
 *
 * The framework is deliberately domain-agnostic: it knows nothing about Python,
 * ruff, pytest, or any particular agent. A concrete workflow is expressed as a
 * `WorkflowDefinition` (see ../workflows/*.ts) plus markdown agent files.
 */

import type { Static, TSchema } from "typebox";

/** Usage accumulated across a role's sub-session. */
export interface UsageTotals {
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	cost: number;
	turns: number;
}

export function emptyUsage(): UsageTotals {
	return { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, turns: 0 };
}

/** Uniform result every gate produces (decision #5). */
export interface GateResult {
	pass: boolean;
	/** Plaintext fed back to the implementer on failure. Required when pass === false. */
	feedback?: string;
	/** Optional machine-readable payload (e.g. the parsed verdict) for UI/logging. */
	structured?: unknown;
	/** Short human label for the dashboard, e.g. "ruff: 3 errors". */
	label?: string;
}

/** Result of running one role's sub-session. */
export interface RoleRunResult {
	role: string;
	/** Final assistant text output. */
	output: string;
	/** Captured structured verdict (present only for verdict states). */
	verdict?: unknown;
	usage: UsageTotals;
	aborted: boolean;
	errorMessage?: string;
}

/**
 * Per-run context handed to gates. The engine mutates `lastRun` before
 * evaluating each transition's gate so verdict gates can read the captured
 * verdict from the state's agent.
 */
export interface RunContext {
	cwd: string;
	baselineRef: string;
	task: TaskSpec;
	taskIndex: number;
	taskCount: number;
	/** Accumulated retro steering notes injected into agents (decision #11). */
	steeringNotes: string;
	/** Per-task handoff note produced by the implementer (decision #3). */
	handoffNote: string;
	signal: AbortSignal;
	/** `git diff <baselineRef>` for the current working tree. */
	diff(): Promise<string>;
	/** Set by the engine to the most recent role result before gate evaluation. */
	lastRun?: RoleRunResult;
}

/** A gate maps the current run context to a pass/fail result. */
export type Gate = (ctx: RunContext) => Promise<GateResult>;

/** An agent role, resolved from a markdown file (frontmatter + body). */
export interface AgentRole {
	name: string;
	/** provider/id or bare id; falls back to the session default when omitted. */
	model?: string;
	/** Built-in / custom tool allowlist for this role. */
	tools?: string[];
	/** System prompt (markdown body). Steering notes are prepended at runtime. */
	systemPrompt: string;
}

/** Configuration for an agent-led verdict state. */
export interface VerdictConfig<S extends TSchema = TSchema> {
	/** Typebox schema the submit_verdict tool exposes as its parameters. */
	schema: S;
	/** Description shown to the model for the submit_verdict tool. */
	toolDescription?: string;
	/** How many times to re-prompt if the agent ends without a verdict (decision #6). */
	maxReprompts: number;
	/** Map the structured verdict to a GateResult. */
	interpret: (verdict: Static<S>) => GateResult;
}

/** A phase in the machine. Terminal when `transitions` is empty. */
export interface State {
	id: string;
	/** AgentRole.name to run for this state, or "" for a pure deterministic gate state. */
	role: string;
	/** Present when this state is an agent-led verdict state. */
	verdict?: VerdictConfig;
	/** Exactly one transition for non-terminal states in v1. */
	transitions: Transition[];
}

export interface Transition {
	gate: Gate;
	onPass: string;
	onFail: string;
	/** Per-transition loop-back cap (decision #8). */
	maxLoops: number;
}

export interface TaskSpec {
	id: string;
	title: string;
	body: string;
}

export interface WorkflowDefinition {
	name: string;
	/** Resolved from markdown agent files, keyed by role name. */
	roles: Record<string, AgentRole>;
	/** The role whose sub-session persists across loop-backs (fix-forward, decision #7). */
	implementerRole: string;
	states: State[];
	initialState: string;
	/** Max total phase executions per task before human escalation (decision #8). */
	globalBudget: number;
}

/** Thrown to stop the whole run (missing verdict, user abort, budget/loop escalation). */
export class WorkflowAbort extends Error {
	constructor(
		message: string,
		readonly kind: "verdict" | "user" | "budget" | "loop" | "error" = "error",
	) {
		super(message);
		this.name = "WorkflowAbort";
	}
}

/**
 * Minimal command execution with AbortSignal support and output truncation.
 * Used for git operations and deterministic gate commands.
 */

import { spawn } from "node:child_process";

export interface ExecOutcome {
	exitCode: number;
	stdout: string;
	stderr: string;
	/** True if the process was killed via the abort signal. */
	aborted: boolean;
	/** True if output was truncated. */
	truncated: boolean;
}

const MAX_OUTPUT_BYTES = 200 * 1024; // 200 KB per stream before truncation

export interface RunCommandOptions {
	cwd: string;
	signal: AbortSignal;
	timeoutMs?: number;
	/** Split a raw command string; when provided, `command` is treated as argv[0]. */
	args?: string[];
}

/**
 * Run a command. When `args` is omitted, `command` is executed through the shell
 * so instantiations can write natural command lines like "ruff check .".
 */
export function runCommand(command: string, opts: RunCommandOptions): Promise<ExecOutcome> {
	return new Promise((resolve) => {
		const useShell = opts.args === undefined;
		const child = useShell
			? spawn(command, { cwd: opts.cwd, shell: true, stdio: ["ignore", "pipe", "pipe"] })
			: spawn(command, opts.args, { cwd: opts.cwd, shell: false, stdio: ["ignore", "pipe", "pipe"] });

		let stdout = "";
		let stderr = "";
		let truncated = false;
		let aborted = false;
		let settled = false;

		const append = (buf: string, chunk: string): string => {
			if (buf.length >= MAX_OUTPUT_BYTES) {
				truncated = true;
				return buf;
			}
			const next = buf + chunk;
			if (next.length > MAX_OUTPUT_BYTES) {
				truncated = true;
				return next.slice(0, MAX_OUTPUT_BYTES);
			}
			return next;
		};

		child.stdout.on("data", (d) => {
			stdout = append(stdout, d.toString());
		});
		child.stderr.on("data", (d) => {
			stderr = append(stderr, d.toString());
		});

		const onAbort = () => {
			aborted = true;
			child.kill("SIGTERM");
		};
		if (opts.signal.aborted) onAbort();
		else opts.signal.addEventListener("abort", onAbort, { once: true });

		let timer: NodeJS.Timeout | undefined;
		if (opts.timeoutMs) {
			timer = setTimeout(() => {
				aborted = true;
				child.kill("SIGTERM");
			}, opts.timeoutMs);
		}

		const finish = (exitCode: number) => {
			if (settled) return;
			settled = true;
			if (timer) clearTimeout(timer);
			opts.signal.removeEventListener("abort", onAbort);
			resolve({ exitCode, stdout, stderr, aborted, truncated });
		};

		child.on("error", (err) => {
			stderr = append(stderr, `\n${(err as Error).message}`);
			finish(127);
		});
		child.on("close", (code) => finish(code ?? 1));
	});
}

/**
 * Git ground-truth helpers (decision #3, #4) and delimited-block extraction for
 * in-memory handoff / steering notes (decision #13: no files written to the repo).
 */

import { runCommand } from "./exec.ts";
import { WorkflowAbort } from "./types.ts";

const DIFF_CAP = 100 * 1024; // cap diff injected into prompts

async function git(args: string[], cwd: string, signal: AbortSignal) {
	return runCommand("git", { cwd, signal, args });
}

/** Ensure we are in a git repo with a clean working tree (decision #4). */
export async function assertCleanTree(cwd: string, signal: AbortSignal): Promise<void> {
	const inside = await git(["rev-parse", "--is-inside-work-tree"], cwd, signal);
	if (inside.exitCode !== 0 || inside.stdout.trim() !== "true") {
		throw new WorkflowAbort(
			"Not a git repository. The workflow requires a git repo to diff against a baseline.",
			"error",
		);
	}
	const status = await git(["status", "--porcelain"], cwd, signal);
	if (status.stdout.trim().length > 0) {
		throw new WorkflowAbort(
			"Working tree is not clean. Commit or stash your changes before running the workflow.",
			"error",
		);
	}
}

/** Record the starting HEAD as the baseline for all diffs. */
export async function getBaselineRef(cwd: string, signal: AbortSignal): Promise<string> {
	const head = await git(["rev-parse", "HEAD"], cwd, signal);
	if (head.exitCode !== 0) {
		throw new WorkflowAbort("Could not resolve HEAD. The repo has no commits yet.", "error");
	}
	return head.stdout.trim();
}

/** `git diff <baselineRef>` including untracked files, capped for prompt injection. */
export async function computeDiff(cwd: string, baselineRef: string, signal: AbortSignal): Promise<string> {
	const tracked = await git(["diff", baselineRef], cwd, signal);
	// Include untracked files as additions.
	const untracked = await git(["ls-files", "--others", "--exclude-standard"], cwd, signal);
	let extra = "";
	for (const file of untracked.stdout.split("\n").map((l) => l.trim()).filter(Boolean)) {
		const d = await git(["diff", "--no-index", "/dev/null", file], cwd, signal);
		extra += d.stdout;
	}
	let combined = tracked.stdout + (extra ? `\n${extra}` : "");
	if (combined.length > DIFF_CAP) {
		combined = `${combined.slice(0, DIFF_CAP)}\n\n[diff truncated at ${DIFF_CAP} bytes]`;
	}
	return combined || "(no changes yet)";
}

/**
 * Extract a delimited block from an agent's final text output.
 * Agents are instructed to emit `### <MARKER>` followed by the block content
 * as the last section of their reply.
 */
export function extractBlock(text: string, marker: string): string | undefined {
	const re = new RegExp(`#{1,6}\\s*${marker}\\s*\\n([\\s\\S]*)$`, "i");
	const m = text.match(re);
	if (!m) return undefined;
	return m[1].trim() || undefined;
}

/**
 * Parse an implementation plan markdown file into an ordered task list
 * (decision #10). The plan is pre-structured by the user.
 *
 * Supported conventions (either may be used in a single file):
 *   1. Heading tasks:   `## Task: <title>` followed by the task body until the
 *      next `## Task:` / `## ` heading.
 *   2. Checklist tasks: top-level `- [ ] <title>` bullets; the body is any
 *      indented lines that follow until the next top-level bullet.
 *
 * Heading tasks take precedence when present.
 */

import { readFileSync } from "node:fs";
import type { TaskSpec } from "./types.ts";
import { WorkflowAbort } from "./types.ts";

const HEADING_TASK = /^#{2,3}\s*Task:\s*(.+?)\s*$/i;
const CHECKLIST_TASK = /^- \[[ xX]\]\s*(.+?)\s*$/;

export function parsePlan(planPath: string): TaskSpec[] {
	let raw: string;
	try {
		raw = readFileSync(planPath, "utf-8");
	} catch {
		throw new WorkflowAbort(`Could not read plan file: ${planPath}`, "error");
	}

	const lines = raw.split("\n");
	const headingTasks = parseHeadingTasks(lines);
	const tasks = headingTasks.length > 0 ? headingTasks : parseChecklistTasks(lines);

	if (tasks.length === 0) {
		throw new WorkflowAbort(
			`No tasks found in ${planPath}. Use '## Task: <title>' sections or '- [ ] <title>' checklist items.`,
			"error",
		);
	}
	return tasks;
}

function parseHeadingTasks(lines: string[]): TaskSpec[] {
	const tasks: TaskSpec[] = [];
	let current: { title: string; body: string[] } | null = null;
	const flush = () => {
		if (current) tasks.push(toTask(tasks.length, current.title, current.body.join("\n")));
	};
	for (const line of lines) {
		const m = line.match(HEADING_TASK);
		if (m) {
			flush();
			current = { title: m[1], body: [] };
		} else if (current) {
			// A new top-level (non-task) heading ends the current task body.
			if (/^#{1,2}\s+\S/.test(line) && !HEADING_TASK.test(line)) {
				flush();
				current = null;
			} else {
				current.body.push(line);
			}
		}
	}
	flush();
	return tasks;
}

function parseChecklistTasks(lines: string[]): TaskSpec[] {
	const tasks: TaskSpec[] = [];
	let current: { title: string; body: string[] } | null = null;
	const flush = () => {
		if (current) tasks.push(toTask(tasks.length, current.title, current.body.join("\n")));
	};
	for (const line of lines) {
		const m = line.match(CHECKLIST_TASK);
		if (m) {
			flush();
			current = { title: m[1], body: [] };
		} else if (current) {
			if (/^\S/.test(line) && line.trim().length > 0) {
				// A new non-indented, non-empty line ends the current task.
				flush();
				current = null;
			} else {
				current.body.push(line);
			}
		}
	}
	flush();
	return tasks;
}

function toTask(index: number, title: string, body: string): TaskSpec {
	const trimmed = body.trim();
	return {
		id: `task-${index + 1}`,
		title,
		body: trimmed.length > 0 ? `${title}\n\n${trimmed}` : title,
	};
}

/**
 * Discover markdown agent files (frontmatter + body) and build AgentRole records.
 * Adapted from examples/extensions/subagent/agents.ts, simplified to a fixed dir.
 */

import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parseFrontmatter } from "@earendil-works/pi-coding-agent";
import type { AgentRole } from "./types.ts";
import { WorkflowAbort } from "./types.ts";

/** Load every *.md in `dir` as an AgentRole keyed by frontmatter `name`. */
export function discoverRoles(dir: string): Record<string, AgentRole> {
	const roles: Record<string, AgentRole> = {};
	let entries: string[];
	try {
		entries = readdirSync(dir).filter((f) => f.endsWith(".md"));
	} catch {
		throw new WorkflowAbort(`Could not read agents directory: ${dir}`, "error");
	}

	for (const file of entries) {
		const filePath = join(dir, file);
		const content = readFileSync(filePath, "utf-8");
		const { frontmatter, body } = parseFrontmatter<Record<string, string>>(content);
		if (!frontmatter.name) continue;
		const tools = frontmatter.tools
			?.split(",")
			.map((t) => t.trim())
			.filter(Boolean);
		roles[frontmatter.name] = {
			name: frontmatter.name,
			model: frontmatter.model,
			tools: tools && tools.length > 0 ? tools : undefined,
			systemPrompt: body.trim(),
		};
	}
	return roles;
}

/** Verify every role referenced by the workflow exists; abort with a clear message otherwise. */
export function assertRolesPresent(roles: Record<string, AgentRole>, required: string[]): void {
	const missing = required.filter((r) => r && !roles[r]);
	if (missing.length > 0) {
		throw new WorkflowAbort(
			`Missing agent definitions for role(s): ${missing.join(", ")}. Add matching *.md files under agents/.`,
			"error",
		);
	}
}

/**
 * Live widget dashboard + milestone session entries (decision #12).
 */

import type { ExtensionAPI, ExtensionCommandContext } from "@earendil-works/pi-coding-agent";
import type { GateResult, UsageTotals } from "./types.ts";

const WIDGET_KEY = "workflow";
const STATUS_KEY = "workflow";
const ENTRY_TYPE = "workflow-milestone";
const MAX_ACTIVITY = 8;

export interface Milestone {
	kind: "state" | "gate" | "escalation" | "start" | "end" | "error";
	task: string;
	state?: string;
	text: string;
	pass?: boolean;
}

export class WorkflowUI {
	private taskIndex = 0;
	private taskCount = 0;
	private taskTitle = "";
	private state = "";
	private loopInfo = "";
	private budget = "";
	private lastGate = "";
	private activity: string[] = [];

	constructor(
		private readonly pi: ExtensionAPI,
		private readonly ctx: ExtensionCommandContext,
	) {}

	setTask(index: number, count: number, title: string) {
		this.taskIndex = index;
		this.taskCount = count;
		this.taskTitle = title;
		this.activity = [];
		this.lastGate = "";
		this.render();
	}

	setState(state: string) {
		this.state = state;
		this.render();
	}

	setLoop(text: string) {
		this.loopInfo = text;
		this.render();
	}

	setBudget(used: number, total: number) {
		this.budget = `${used}/${total}`;
		this.render();
	}

	setGate(result: GateResult) {
		this.lastGate = `${result.pass ? "✓" : "✗"} ${result.label ?? (result.pass ? "pass" : "fail")}`;
		this.render();
	}

	pushActivity(line: string) {
		this.activity.push(line);
		if (this.activity.length > MAX_ACTIVITY) this.activity.shift();
		this.render();
	}

	private render() {
		const lines = [
			`⚙ Workflow — task ${this.taskIndex + 1}/${this.taskCount}: ${this.taskTitle}`,
			`  state: ${this.state}   loops: ${this.loopInfo || "-"}   budget: ${this.budget || "-"}   gate: ${this.lastGate || "-"}`,
			...this.activity.map((a) => `    ${a}`),
		];
		this.ctx.ui.setWidget(WIDGET_KEY, lines);
		this.ctx.ui.setStatus(STATUS_KEY, `workflow ${this.taskIndex + 1}/${this.taskCount} · ${this.state}`);
	}

	milestone(m: Milestone) {
		this.pi.appendEntry<Milestone>(ENTRY_TYPE, m);
	}

	notify(message: string, type: "info" | "warning" | "error" = "info") {
		this.ctx.ui.notify(message, type);
	}

	async escalate(reason: string): Promise<"retry" | "abort" | "accept"> {
		const choice = await this.ctx.ui.select(`Workflow paused: ${reason}`, [
			"Retry (reset the counter and continue)",
			"Abort the workflow",
			"Accept and continue (treat current gate as pass)",
		]);
		if (choice?.startsWith("Retry")) return "retry";
		if (choice?.startsWith("Accept")) return "accept";
		return "abort";
	}

	summarizeUsage(u: UsageTotals): string {
		return `${u.turns} turns · ↑${u.input} ↓${u.output} · $${u.cost.toFixed(4)}`;
	}

	clear() {
		this.ctx.ui.setWidget(WIDGET_KEY, undefined);
		this.ctx.ui.setStatus(STATUS_KEY, undefined);
	}
}

/**
 * Role invocation via SDK in-process sub-sessions (decision #1).
 *
 * - Each non-implementer role runs in a fresh isolated AgentSession and is
 *   disposed after producing its output/verdict.
 * - The implementer role's session persists across loop-backs so feedback is
 *   delivered as a follow-up (fix-forward, decision #7).
 * - Verdict roles get read-only tools + a `submit_verdict` terminating tool
 *   whose parameters are captured in a closure (decision #6).
 */

import {
	type AgentSession,
	createAgentSession,
	DefaultResourceLoader,
	defineTool,
	type ExtensionCommandContext,
	type ModelRuntime,
	resolveCliModel,
	SessionManager,
} from "@earendil-works/pi-coding-agent";
import type { AgentRole, RoleRunResult, State, TaskSpec, VerdictConfig } from "./types.ts";
import { emptyUsage, WorkflowAbort } from "./types.ts";
import type { WorkflowUI } from "./ui.ts";

export interface RunStateOptions {
	task: TaskSpec;
	steeringNotes: string;
	diff: string;
	handoffNote: string;
	/** Present when routing back to the implementer after a gate failure. */
	feedback?: string;
}

const READONLY_TOOLS = ["read", "grep", "find", "ls"];
const IMPLEMENTER_TOOLS = ["read", "write", "edit", "bash"];

export class WorkflowRunner {
	private implementerSession: AgentSession | null = null;
	private implementerStarted = false;

	constructor(
		private readonly deps: {
			cwd: string;
			agentDir: string;
			modelRuntime: ModelRuntime;
			roles: Record<string, AgentRole>;
			implementerRole: string;
			ui: WorkflowUI;
			signal: AbortSignal;
			ctx: ExtensionCommandContext;
		},
	) {}

	async runState(state: State, opts: RunStateOptions): Promise<RoleRunResult> {
		const role = this.deps.roles[state.role];
		if (!role) throw new WorkflowAbort(`No agent role '${state.role}' defined.`, "error");

		const isImplementer = state.role === this.deps.implementerRole;
		const usage = emptyUsage();
		let lastText = "";
		const captured: { value: unknown } = { value: undefined };

		const verdictConfig = state.verdict;
		const customTools = verdictConfig ? [this.makeVerdictTool(verdictConfig, captured)] : undefined;

		// Acquire a session (reuse persistent implementer session across loop-backs).
		let session: AgentSession;
		let ownSession: boolean;
		if (isImplementer && this.implementerSession) {
			session = this.implementerSession;
			ownSession = false;
		} else {
			session = await this.createRoleSession(role, opts.steeringNotes, this.roleTools(role, verdictConfig), customTools);
			if (isImplementer) {
				this.implementerSession = session;
				ownSession = false; // disposed in endTask()
			} else {
				ownSession = true;
			}
		}

		const unsub = session.subscribe((ev: any) => {
			if (ev.type === "tool_execution_start") {
				this.deps.ui.pushActivity(`${role.name}: ${formatTool(ev.toolName, ev.args)}`);
			} else if (ev.type === "message_end" && ev.message?.role === "assistant") {
				usage.turns++;
				const u = ev.message.usage;
				if (u) {
					usage.input += u.input || 0;
					usage.output += u.output || 0;
					usage.cacheRead += u.cacheRead || 0;
					usage.cacheWrite += u.cacheWrite || 0;
					usage.cost += u.cost?.total || 0;
				}
				const text = extractText(ev.message.content);
				if (text.trim()) lastText = text;
			}
		});

		try {
			if (isImplementer) {
				if (opts.feedback && this.implementerStarted) {
					await session.followUp(opts.feedback);
					await session.waitForIdle();
				} else {
					await session.prompt(buildImplementerPrompt(opts));
					this.implementerStarted = true;
				}
			} else {
				await session.prompt(buildAgentPrompt(state, opts));
				if (verdictConfig) {
					let tries = 0;
					while (captured.value === undefined && tries < verdictConfig.maxReprompts && !this.deps.signal.aborted) {
						tries++;
						this.deps.ui.pushActivity(`${role.name}: no verdict — reprompt ${tries}/${verdictConfig.maxReprompts}`);
						await session.followUp(
							"You did not submit a verdict. You MUST call the submit_verdict tool now with your structured judgement. Do not reply with prose.",
						);
						await session.waitForIdle();
					}
					if (captured.value === undefined) {
						throw new WorkflowAbort(
							`Role '${role.name}' never called submit_verdict after ${verdictConfig.maxReprompts} reprompt(s).`,
							"verdict",
						);
					}
				}
			}
		} finally {
			unsub();
			if (ownSession) session.dispose();
		}

		return {
			role: role.name,
			output: lastText,
			verdict: captured.value,
			usage,
			aborted: this.deps.signal.aborted,
		};
	}

	/** Dispose the persistent implementer session at the end of a task. */
	endTask(): void {
		if (this.implementerSession) {
			this.implementerSession.dispose();
			this.implementerSession = null;
		}
		this.implementerStarted = false;
	}

	disposeAll(): void {
		this.endTask();
	}

	private async createRoleSession(
		role: AgentRole,
		steeringNotes: string,
		tools: string[] | undefined,
		customTools: ReturnType<typeof defineTool>[] | undefined,
	): Promise<AgentSession> {
		const systemPrompt = buildSystemPrompt(role, steeringNotes);
		const loader = new DefaultResourceLoader({
			cwd: this.deps.cwd,
			agentDir: this.deps.agentDir,
			noExtensions: true, // critical: sub-sessions must not recursively load this extension (risk #5)
			noSkills: true,
			noPromptTemplates: true,
			noThemes: true,
			noContextFiles: true,
			systemPrompt,
		});
		await loader.reload();

		const model = this.resolveModel(role.model);
		const { session } = await createAgentSession({
			cwd: this.deps.cwd,
			agentDir: this.deps.agentDir,
			modelRuntime: this.deps.modelRuntime,
			model,
			tools,
			customTools,
			resourceLoader: loader,
			sessionManager: SessionManager.inMemory(this.deps.cwd),
		});

		// Propagate abort to the sub-session.
		if (this.deps.signal.aborted) void session.abort();
		else this.deps.signal.addEventListener("abort", () => void session.abort(), { once: true });

		return session;
	}

	private resolveModel(spec?: string) {
		if (!spec) return undefined;
		const r = resolveCliModel({ cliModel: spec, modelRuntime: this.deps.modelRuntime });
		if (r.error || !r.model) {
			this.deps.ui.notify(`Model '${spec}' not resolved (${r.error ?? "unknown"}); using session default.`, "warning");
			return undefined;
		}
		return r.model;
	}

	private roleTools(role: AgentRole, verdictConfig?: VerdictConfig): string[] | undefined {
		const isImplementer = role.name === this.deps.implementerRole;
		let tools = role.tools ?? (isImplementer ? IMPLEMENTER_TOOLS : READONLY_TOOLS);
		if (verdictConfig && !tools.includes("submit_verdict")) {
			tools = [...tools, "submit_verdict"];
		}
		return tools;
	}

	private makeVerdictTool(config: VerdictConfig, captured: { value: unknown }) {
		return defineTool({
			name: "submit_verdict",
			label: "Submit Verdict",
			description:
				config.toolDescription ??
				"Submit your final structured verdict. This ends your turn — call it exactly once as your last action.",
			parameters: config.schema,
			async execute(_id, params) {
				captured.value = params;
				return {
					content: [{ type: "text", text: "Verdict recorded." }],
					details: params as Record<string, unknown>,
					terminate: true,
				};
			},
		});
	}
}

// ---- prompt builders ---------------------------------------------------------

function buildSystemPrompt(role: AgentRole, steeringNotes: string): string {
	if (!steeringNotes.trim()) return role.systemPrompt;
	return `${role.systemPrompt}\n\n## Implementation notes from previous tasks (steering)\n${steeringNotes.trim()}`;
}

function buildImplementerPrompt(opts: RunStateOptions): string {
	return [
		"Implement the following task. Keep changes tightly scoped to this task only.",
		"",
		"## Task",
		opts.task.body,
		"",
		"When finished, end your reply with a section exactly like:",
		"### HANDOFF",
		"- Files changed: ...",
		"- Key decisions: ...",
		"- Assumptions / follow-ups: ...",
	].join("\n");
}

function buildAgentPrompt(state: State, opts: RunStateOptions): string {
	const diffBlock = ["## Diff since baseline", "```diff", opts.diff, "```"].join("\n");
	if (state.verdict) {
		return [
			"Judge the change described below against your role's criteria.",
			"",
			"## Task goal",
			opts.task.body,
			"",
			"## Implementer handoff note",
			opts.handoffNote || "(none provided)",
			"",
			diffBlock,
			"",
			"Do NOT modify any files. End by calling the submit_verdict tool exactly once with your structured judgement.",
		].join("\n");
	}
	// Retro-style role: update docs and emit steering notes.
	return [
		"The task below has passed validation and review. Update documentation as needed and capture steering notes.",
		"",
		"## Task goal",
		opts.task.body,
		"",
		diffBlock,
		"",
		"Update any relevant docs (README, module docs) to reflect these changes.",
		"Then end your reply with a section exactly like:",
		"### STEERING_NOTES",
		"Concise bullets of gotchas / conventions / context useful for the REMAINING tasks. Omit the section if nothing is notable.",
	].join("\n");
}

// ---- helpers -----------------------------------------------------------------

function extractText(content: unknown): string {
	if (!Array.isArray(content)) return "";
	return content
		.filter((p: any) => p?.type === "text" && typeof p.text === "string")
		.map((p: any) => p.text)
		.join("");
}

function truncate(s: unknown, n = 60): string {
	const str = String(s ?? "");
	return str.length > n ? `${str.slice(0, n)}…` : str;
}

function formatTool(name: string, args: any): string {
	switch (name) {
		case "bash":
			return `$ ${truncate(args?.command)}`;
		case "read":
			return `read ${truncate(args?.path, 48)}`;
		case "edit":
			return `edit ${truncate(args?.path, 48)}`;
		case "write":
			return `write ${truncate(args?.path, 48)}`;
		case "grep":
			return `grep ${truncate(args?.pattern, 32)}`;
		case "submit_verdict":
			return "submit_verdict";
		default:
			return name;
	}
}

/**
 * Gate primitives (decision #5). Both deterministic and agent-led gates return
 * the uniform `GateResult` so the engine routes transitions identically.
 */

import type { Static, TSchema } from "typebox";
import { runCommand } from "./exec.ts";
import type { Gate, GateResult, RunContext } from "./types.ts";

export interface DeterministicGateSpec {
	/** Human label for the dashboard, e.g. "ruff". */
	name: string;
	/** Shell command line, e.g. "ruff check .". */
	command: string;
	timeoutMs?: number;
	/** Override the default exit-code interpretation. */
	interpret?: (r: { exitCode: number; stdout: string; stderr: string }) => GateResult;
}

/**
 * A deterministic gate that runs a shell command. Passes iff exit code 0.
 * On failure, the combined stderr/stdout becomes the feedback fed to the
 * implementer verbatim (decision: feedback stays plaintext in v1).
 */
export function deterministicGate(spec: DeterministicGateSpec): Gate {
	return async (ctx: RunContext): Promise<GateResult> => {
		const r = await runCommand(spec.command, {
			cwd: ctx.cwd,
			signal: ctx.signal,
			timeoutMs: spec.timeoutMs,
		});
		if (spec.interpret) return spec.interpret(r);
		if (r.exitCode === 0) {
			return { pass: true, label: `${spec.name}: ok` };
		}
		const output = [r.stdout, r.stderr].filter(Boolean).join("\n").trim();
		return {
			pass: false,
			label: `${spec.name}: failed (exit ${r.exitCode})`,
			feedback: [
				`The \`${spec.name}\` check failed (\`${spec.command}\`, exit code ${r.exitCode}).`,
				"Fix the issues below, then finish.",
				"",
				output || "(no output captured)",
			].join("\n"),
			structured: { exitCode: r.exitCode },
		};
	};
}

/** An arbitrary JS predicate gate. */
export function fnGate(fn: (ctx: RunContext) => Promise<GateResult>): Gate {
	return fn;
}

/**
 * A gate that reads the structured verdict captured by the state's agent
 * (via the submit_verdict tool) and maps it to a GateResult. The runner
 * guarantees a verdict is present (or aborts), so `interpret` always receives one.
 */
export function agentVerdictGate<S extends TSchema>(interpret: (verdict: Static<S>) => GateResult): Gate {
	return async (ctx: RunContext): Promise<GateResult> => {
		const verdict = ctx.lastRun?.verdict as Static<S> | undefined;
		if (verdict === undefined) {
			// Defensive: should be unreachable because the runner enforces submission.
			return { pass: false, label: "verdict missing", feedback: "No verdict was produced." };
		}
		return interpret(verdict);
	};
}

/**
 * The deterministic state-machine driver.
 *
 * Outer loop iterates tasks in order; the inner loop walks the phase graph,
 * evaluating each transition's gate and routing back to the implementer on
 * failure (feedback as plaintext) until the terminal state is reached.
 */

import { assertCleanTree, computeDiff, extractBlock, getBaselineRef } from "./handoff.ts";
import { parsePlan } from "./plan-parser.ts";
import { WorkflowRunner } from "./runner.ts";
import type { RunContext, State, TaskSpec, WorkflowDefinition } from "./types.ts";
import { WorkflowAbort } from "./types.ts";
import type { WorkflowUI } from "./ui.ts";

export interface EngineDeps {
	cwd: string;
	agentDir: string;
	modelRuntime: import("@earendil-works/pi-coding-agent").ModelRuntime;
	ui: WorkflowUI;
	ctx: import("@earendil-works/pi-coding-agent").ExtensionCommandContext;
	signal: AbortSignal;
	planPath: string;
}

export async function runWorkflow(def: WorkflowDefinition, deps: EngineDeps): Promise<void> {
	const { cwd, ui, signal } = deps;

	await assertCleanTree(cwd, signal);
	const baselineRef = await getBaselineRef(cwd, signal);
	const tasks = parsePlan(deps.planPath);

	const stateMap = new Map<string, State>(def.states.map((s) => [s.id, s]));
	const runner = new WorkflowRunner({
		cwd,
		agentDir: deps.agentDir,
		modelRuntime: deps.modelRuntime,
		roles: def.roles,
		implementerRole: def.implementerRole,
		ui,
		signal,
		ctx: deps.ctx,
	});

	let steeringNotes = "";

	try {
		for (let taskIndex = 0; taskIndex < tasks.length; taskIndex++) {
			const task = tasks[taskIndex];
			ui.setTask(taskIndex, tasks.length, task.title);
			ui.milestone({ kind: "start", task: task.title, text: `Starting task ${taskIndex + 1}/${tasks.length}` });

			let handoffNote = "";
			const ctx: RunContext = {
				cwd,
				baselineRef,
				task,
				taskIndex,
				taskCount: tasks.length,
				steeringNotes,
				handoffNote,
				signal,
				diff: () => computeDiff(cwd, baselineRef, signal),
			};

			let state = def.initialState;
			const loopCounts = new Map<string, number>();
			let budgetUsed = 0;
			let pendingFeedback: string | undefined;

			while (true) {
				if (signal.aborted) throw new WorkflowAbort("Aborted by user.", "user");
				const st = stateMap.get(state);
				if (!st) throw new WorkflowAbort(`Unknown state '${state}'.`, "error");
				if (st.transitions.length === 0) break; // terminal
				ui.setState(st.id);

				// Run the state's agent, if any.
				if (st.role) {
					const needsDiff = st.role !== def.implementerRole;
					const diff = needsDiff ? await ctx.diff() : "";
					const result = await runner.runState(st, {
						task,
						steeringNotes,
						diff,
						handoffNote,
						feedback: pendingFeedback,
					});
					pendingFeedback = undefined;
					if (result.aborted || signal.aborted) throw new WorkflowAbort("Aborted by user.", "user");
					ctx.lastRun = result;

					if (st.role === def.implementerRole) {
						const h = extractBlock(result.output, "HANDOFF");
						if (h) {
							handoffNote = h;
							ctx.handoffNote = h;
						}
					} else if (!st.verdict) {
						const s = extractBlock(result.output, "STEERING_NOTES");
						if (s) steeringNotes = appendSteering(steeringNotes, task, s);
					}
					ui.milestone({ kind: "state", task: task.title, state: st.id, text: ui.summarizeUsage(result.usage) });
				} else {
					ctx.lastRun = undefined;
				}

				// Evaluate the (single) transition's gate.
				const tr = st.transitions[0];
				const gateResult = await tr.gate(ctx);
				budgetUsed++;
				ui.setBudget(budgetUsed, def.globalBudget);
				ui.setGate(gateResult);
				ui.milestone({
					kind: "gate",
					task: task.title,
					state: st.id,
					pass: gateResult.pass,
					text: gateResult.label ?? (gateResult.pass ? "pass" : "fail"),
				});

				// Global budget escalation.
				if (budgetUsed > def.globalBudget) {
					const decision = await ui.escalate(`global budget (${def.globalBudget}) exhausted on "${task.title}"`);
					if (decision === "abort") throw new WorkflowAbort("Aborted at budget escalation.", "budget");
					if (decision === "accept") break; // move on to next task
					budgetUsed = 0; // retry
				}

				if (gateResult.pass) {
					state = tr.onPass;
					continue;
				}

				// Failure routing with per-transition loop caps.
				const key = `${st.id}->${tr.onFail}`;
				const count = (loopCounts.get(key) ?? 0) + 1;
				loopCounts.set(key, count);
				ui.setLoop(`${st.id} ×${count}/${tr.maxLoops}`);

				if (count > tr.maxLoops) {
					const decision = await ui.escalate(`loop cap (${tr.maxLoops}) hit at "${st.id}" on "${task.title}"`);
					ui.milestone({ kind: "escalation", task: task.title, state: st.id, text: `loop cap → ${decision}` });
					if (decision === "abort") throw new WorkflowAbort(`Aborted at loop cap on '${st.id}'.`, "loop");
					if (decision === "accept") {
						state = tr.onPass;
						continue;
					}
					loopCounts.set(key, 0); // retry
				}

				pendingFeedback = gateResult.feedback;
				state = tr.onFail;
			}

			runner.endTask();
			ui.milestone({ kind: "end", task: task.title, text: `Completed task ${taskIndex + 1}/${tasks.length}` });
		}
	} finally {
		runner.disposeAll();
	}
}

function appendSteering(existing: string, task: TaskSpec, notes: string): string {
	const block = `### From ${task.title}\n${notes.trim()}`;
	return existing.trim() ? `${existing.trim()}\n\n${block}` : block;
}

/**
 * State-machine multi-agent workflow extension.
 *
 * Usage: /workflow <path-to-plan.md>
 *
 * Drives a deterministic implement → gate → validate → review → retro pipeline
 * per task, using isolated SDK sub-sessions for each agent role. See plan.md for
 * the full design and rationale.
 */

import { dirname, isAbsolute, join } from "node:path";
import {
	type ExtensionAPI,
	getAgentDir,
	ModelRuntime,
} from "@earendil-works/pi-coding-agent";
import { assertRolesPresent, discoverRoles } from "./framework/agents.ts";
import { runWorkflow } from "./framework/engine.ts";
import { WorkflowUI } from "./framework/ui.ts";
import { WorkflowAbort } from "./framework/types.ts";
import { buildPythonWorkflow } from "./workflows/python.ts";

// Resolve this extension's directory so we can find agents/ regardless of cwd.
const EXT_DIR = dirname(new URL(import.meta.url).pathname);
const AGENTS_DIR = join(EXT_DIR, "agents");

export default function (pi: ExtensionAPI) {
	let modelRuntime: ModelRuntime | undefined;
	// Active run controller, so shutdown can abort a running workflow.
	let activeController: AbortController | undefined;

	pi.on("session_shutdown", async () => {
		activeController?.abort();
	});

	pi.registerCommand("workflow", {
		description: "Run the deterministic multi-agent workflow: /workflow <plan-path>",
		handler: async (args, ctx) => {
			if (!ctx.hasUI) {
				ctx.ui.notify("The workflow command requires interactive UI.", "error");
				return;
			}
			const planPath = resolvePlanPath(args.trim(), ctx.cwd);
			if (!planPath) {
				ctx.ui.notify("Usage: /workflow <path-to-plan.md>", "warning");
				return;
			}

			const controller = new AbortController();
			activeController = controller;
			const ui = new WorkflowUI(pi, ctx);

			try {
				if (!modelRuntime) modelRuntime = await ModelRuntime.create();

				const roles = discoverRoles(AGENTS_DIR);
				const def = buildPythonWorkflow(roles);
				assertRolesPresent(roles, [def.implementerRole, ...def.states.map((s) => s.role).filter(Boolean)]);

				ui.notify(`Starting workflow "${def.name}" on ${planPath}`, "info");
				await runWorkflow(def, {
					cwd: ctx.cwd,
					agentDir: getAgentDir(),
					modelRuntime,
					ui,
					ctx,
					signal: controller.signal,
					planPath,
				});
				ui.notify("Workflow completed.", "info");
			} catch (err) {
				if (err instanceof WorkflowAbort) {
					ui.notify(`Workflow stopped (${err.kind}): ${err.message}`, err.kind === "user" ? "warning" : "error");
					ui.notify("Any partial changes remain in your working tree (git diff to inspect).", "warning");
				} else {
					ui.notify(`Workflow error: ${(err as Error).message}`, "error");
				}
			} finally {
				ui.clear();
				activeController = undefined;
			}
		},
	});
}

function resolvePlanPath(arg: string, cwd: string): string | undefined {
	if (!arg) return undefined;
	return isAbsolute(arg) ? arg : join(cwd, arg);
}

/**
 * Concrete instantiation: a Python project workflow.
 *
 * Pipeline (per task):
 *   implement → ruff → ty → pytest → validate → review → retro → done
 * Deterministic gates run ruff/ty/pytest; validate/review are agent-led verdicts.
 * Any gate failure routes back to the implementer with plaintext feedback.
 *
 * This file is the ONLY place that names ruff/ty/pytest or the concrete roles;
 * the framework stays domain-agnostic.
 */

import { StringEnum } from "@earendil-works/pi-ai";
import { type Static, Type } from "typebox";
import { agentVerdictGate, deterministicGate, fnGate } from "../framework/gates.ts";
import type { AgentRole, GateResult, State, WorkflowDefinition } from "../framework/types.ts";

// ---- verdict schemas ---------------------------------------------------------

const Issue = Type.Object({
	severity: StringEnum(["blocker", "major", "minor"]),
	description: Type.String({ description: "What is wrong" }),
	location: Type.Optional(Type.String({ description: "file:line or symbol, if applicable" })),
});

const ValidatorVerdict = Type.Object({
	verdict: StringEnum(["pass", "fail"]),
	issues: Type.Array(Issue, { description: "Concrete problems found in the change" }),
	summary: Type.String({ description: "One-paragraph rationale" }),
});

const ReviewerVerdict = Type.Object({
	verdict: StringEnum(["pass", "fail"]),
	goalMet: Type.Boolean({ description: "Does the change implement the task goal from the plan?" }),
	adheresToConventions: Type.Boolean({ description: "Does it follow the project's conventions and general good practice?" }),
	issues: Type.Array(Issue),
	summary: Type.String(),
});

// ---- verdict interpreters ----------------------------------------------------

function formatIssues(issues: Static<typeof Issue>[]): string {
	if (issues.length === 0) return "(no specific issues listed)";
	return issues
		.map((i) => `- [${i.severity}] ${i.description}${i.location ? ` (${i.location})` : ""}`)
		.join("\n");
}

function interpretValidator(v: Static<typeof ValidatorVerdict>): GateResult {
	const hasBlocker = v.issues.some((i) => i.severity === "blocker");
	const pass = v.verdict === "pass" && !hasBlocker;
	if (pass) return { pass: true, label: "validator: pass", structured: v };
	return {
		pass: false,
		label: `validator: fail (${v.issues.length} issue${v.issues.length === 1 ? "" : "s"})`,
		structured: v,
		feedback: ["Validation failed.", v.summary, "", "Issues:", formatIssues(v.issues)].join("\n"),
	};
}

function interpretReviewer(v: Static<typeof ReviewerVerdict>): GateResult {
	const pass = v.verdict === "pass" && v.goalMet && v.adheresToConventions;
	if (pass) return { pass: true, label: "reviewer: pass", structured: v };
	return {
		pass: false,
		label: "reviewer: fail",
		structured: v,
		feedback: [
			"Review failed.",
			v.summary,
			`goal met: ${v.goalMet} · adheres to conventions: ${v.adheresToConventions}`,
			"",
			"Issues:",
			formatIssues(v.issues),
		].join("\n"),
	};
}

// ---- deterministic gate commands (edit these for your project) ---------------

const RUFF_COMMAND = "ruff check .";
const TY_COMMAND = "ty check";
const PYTEST_COMMAND = "pytest -q";

const alwaysPass = fnGate(async () => ({ pass: true }));

export function buildPythonWorkflow(roles: Record<string, AgentRole>): WorkflowDefinition {
	const states: State[] = [
		{
			id: "implement",
			role: "implementer",
			transitions: [{ gate: alwaysPass, onPass: "ruff", onFail: "implement", maxLoops: 1 }],
		},
		{
			id: "ruff",
			role: "",
			transitions: [
				{ gate: deterministicGate({ name: "ruff", command: RUFF_COMMAND }), onPass: "ty", onFail: "implement", maxLoops: 3 },
			],
		},
		{
			id: "ty",
			role: "",
			transitions: [
				{ gate: deterministicGate({ name: "ty", command: TY_COMMAND }), onPass: "pytest", onFail: "implement", maxLoops: 3 },
			],
		},
		{
			id: "pytest",
			role: "",
			transitions: [
				{
					gate: deterministicGate({ name: "pytest", command: PYTEST_COMMAND, timeoutMs: 10 * 60_000 }),
					onPass: "validate",
					onFail: "implement",
					maxLoops: 3,
				},
			],
		},
		{
			id: "validate",
			role: "validator",
			verdict: { schema: ValidatorVerdict, maxReprompts: 2, interpret: interpretValidator },
			transitions: [
				{ gate: agentVerdictGate<typeof ValidatorVerdict>(interpretValidator), onPass: "review", onFail: "implement", maxLoops: 3 },
			],
		},
		{
			id: "review",
			role: "reviewer",
			verdict: { schema: ReviewerVerdict, maxReprompts: 2, interpret: interpretReviewer },
			transitions: [
				{ gate: agentVerdictGate<typeof ReviewerVerdict>(interpretReviewer), onPass: "retro", onFail: "implement", maxLoops: 2 },
			],
		},
		{
			id: "retro",
			role: "retro",
			transitions: [{ gate: alwaysPass, onPass: "done", onFail: "done", maxLoops: 1 }],
		},
		{ id: "done", role: "", transitions: [] },
	];

	return {
		name: "python-implement",
		roles,
		implementerRole: "implementer",
		states,
		initialState: "implement",
		globalBudget: 40,
	};
}

